class Solution {
  public int binarySearchableNumbers(int[] nums) {
    // searchable exactly when larger than everything to its left and smaller than everything to its right
    int n = nums.length;
    int[] minRight = new int[n + 1];
    minRight[n] = Integer.MAX_VALUE;
    for (int i = n - 1; i >= 0; i--) minRight[i] = Math.min(minRight[i + 1], nums[i]);
    int count = 0, maxLeft = Integer.MIN_VALUE;
    for (int i = 0; i < n; i++) {
      if (nums[i] > maxLeft && nums[i] < minRight[i + 1]) count++;
      maxLeft = Math.max(maxLeft, nums[i]);
    }
    return count;
  }
}
